const calcJS=`<script>
const $=id=>+document.getElementById(id).value||0,fm=n=>isFinite(n)?n.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}):'—',pc=n=>isFinite(n)?(n*100).toFixed(1)+'%':'—',x=n=>isFinite(n)?n.toFixed(2)+'x':'—';
function calc(){document.querySelectorAll('[data-calc]').forEach(f=>{const k=f.dataset.calc,o=f.querySelector('output');let r='';
if(k=='bond'){const v=$('b_val'),c=$('b_cost'),a=$('b_asmt'),cov=$('b_cov')||1.2,rt=$('b_rate')/100,yr=$('b_term');const cap=v/3;const ann=a/cov;const pv=rt>0?ann*(1-Math.pow(1+rt,-yr))/rt:ann*yr;const size=Math.min(cap,pv);r=\`<b>Value-to-lien cap (3:1):</b> \${fm(cap)}<br><b>Supportable by assessments at \${x(cov)}:</b> \${fm(pv)}<br><b>Indicative maximum bond size:</b> \${fm(size)}<br><b>Share of improvement cost covered:</b> \${c?pc(Math.min(size,c)/c):'—'}\`;}
if(k=='flip'){const p=$('f_p'),rh=$('f_r'),arv=$('f_arv'),mo=$('f_m'),rt=$('f_rate')/100,lp=$('f_ltp')/100,sc=$('f_sell')/100,cc=$('f_close')/100;const cont=rh*.1,loan=p*lp+rh,int=loan*rt/12*mo,costs=p+rh+cont+int+p*cc+arv*sc,profit=arv-costs,cash=p*(1-lp)+cont+int+p*cc;r=\`<b>Estimated loan (incl. 100% rehab):</b> \${fm(loan)}<br><b>Interest carry (\${mo} mo, interest-only):</b> \${fm(int)}<br><b>10% contingency:</b> \${fm(cont)}<br><b>Estimated profit:</b> \${fm(profit)} (\${pc(profit/arv)} of ARV)<br><b>Cash-on-cash:</b> \${pc(profit/cash)}<br><b>70% rule max purchase:</b> \${fm(arv*.7-rh)}\`;}
if(k=='build'){const land=$('c_land'),hard=$('c_hard'),soft=$('c_soft')/100,cont=$('c_cont')/100,ltc=$('c_ltc')/100,mo=$('c_mo'),rt=$('c_rate')/100;const s=hard*soft,ct=hard*cont,tot=land+hard+s+ct,loan=tot*ltc,intr=loan*.6*rt/12*mo;r=\`<b>Soft costs:</b> \${fm(s)} · <b>Contingency:</b> \${fm(ct)}<br><b>Total project cost:</b> \${fm(tot)}<br><b>Loan at \${pc(ltc)} LTC:</b> \${fm(loan)} · <b>Equity required:</b> \${fm(tot-loan)}<br><b>Est. interest reserve</b> (avg. 60% drawn): \${fm(intr)}<br><b>Indicative monthly draw</b> (hard costs, straight-line): \${fm(hard/mo)}\`;}
if(k=='bridge'){const ln=$('br_loan'),noi=$('br_noi'),rt=$('br_rate')/100,am=$('br_am'),dscr=$('br_dscr'),v=$('br_val'),ltv=$('br_ltv')/100;const mr=rt/12,n=am*12,pmt=mr>0?ln*mr/(1-Math.pow(1+mr,-n)):ln/n,ds=pmt*12,cur=noi/ds;const maxD=noi/dscr/12,maxL=Math.min(mr>0?maxD*(1-Math.pow(1+mr,-n))/mr:maxD*n,v*ltv);r=\`<b>Refi DSCR on current balance:</b> \${x(cur)} \${cur>=dscr?'✓ meets':'✗ below'} \${x(dscr)} target<br><b>Max refi loan</b> (lesser of DSCR and \${pc(ltv)} LTV): \${fm(maxL)}<br><b>Shortfall / surplus vs. bridge payoff:</b> \${fm(maxL-ln)}\`;}
o.innerHTML=r;});}
document.addEventListener('input',calc);document.addEventListener('DOMContentLoaded',calc);</script>`;
